import{at as e,it as t,n,vt as r}from"./chunks/framework.BUQROvXk.js";var i=JSON.parse(`{"title":"@jsprismarine/console-protocol","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/console-protocol/index.md","filePath":"api/@jsprismarine/console-protocol/index.md"}`),a={name:`api/@jsprismarine/console-protocol/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<p><a href="./../../">JSPrismarine</a> / @jsprismarine/console-protocol</p><h1 id="jsprismarine-console-protocol" tabindex="-1">@jsprismarine/console-protocol <a class="header-anchor" href="#jsprismarine-console-protocol" aria-label="Permalink to “@jsprismarine/console-protocol”">​</a></h1><p><a href="https://discord.gg/6w8JWhy" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/704967868885762108?color=%237289DA&amp;label=Discord" alt="Join the Discord Server"></a><a href="https://www.npmjs.com/package/@jsprismarine/console-protocol" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/dt/@jsprismarine/console-protocol" alt="npm"></a></p><p>Message types and links between the JSPrismarine server and its console.</p><p>When the server runs under the terminal UI it is a child process, and the two sides talk over Node&#39;s IPC channel. This package defines what they say to each other and how a message gets from one side to the other. It depends only on <code>@jsprismarine/logger</code> (for <code>LogLevel</code>), so neither the server nor the host pulls in a renderer by importing it.</p><p>There are three message families. <code>ServerMessage</code> is everything the server sends: <code>hello</code> on connect, <code>log</code> records with a sequence number and <code>log.dropped</code> when the server had to shed records, <code>status</code> with TPS, player count, memory, and uptime, <code>lifecycle</code> state changes, and <code>command.result</code> and <code>complete.result</code> replies. <code>ConsoleMessage</code> is what the console sends back: <code>command</code>, <code>complete</code>, <code>subscribe</code> to set the log level, and <code>shutdown</code>. <code>SupervisorEvent</code> never crosses the channel; the host raises it for the UI to describe its own state (watching, a changed path, regenerating data, a restart, raw child output).</p><p>A <code>MessageLink&lt;In, Out&gt;</code> is the channel itself: <code>send</code>, <code>onMessage</code>, <code>onClose</code>, <code>close</code>. <code>send</code> returns <code>false</code> when the channel asks the sender to slow down. Three adapters implement it: <code>childProcessLink()</code> on the server side over <code>process.send</code>, <code>subprocessLink(child)</code> on the host side over the spawned child, and <code>memoryLinkPair()</code> for tests. <code>isServerMessage</code> and <code>isConsoleMessage</code> check that incoming JSON has one of the known shapes before you trust it.</p><h2 id="exports" tabindex="-1">Exports <a class="header-anchor" href="#exports" aria-label="Permalink to “Exports”">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Kind</th></tr></thead><tbody><tr><td><code>PROTOCOL_VERSION</code></td><td>constant, currently <code>1</code>; every message carries it as <code>v</code></td></tr><tr><td><code>ServerMessage</code>, <code>ServerMessageType</code>, <code>LogEntry</code>, <code>LifecycleState</code></td><td>types for the server side</td></tr><tr><td><code>ConsoleMessage</code>, <code>ConsoleMessageType</code></td><td>types for the console side</td></tr><tr><td><code>SupervisorEvent</code>, <code>SupervisorState</code></td><td>types for host-local events</td></tr><tr><td><code>isServerMessage</code>, <code>isConsoleMessage</code></td><td>type guards</td></tr><tr><td><code>MessageLink</code>, <code>LinkOptions</code></td><td>the channel interface and adapter options</td></tr><tr><td><code>childProcessLink</code>, <code>subprocessLink</code>, <code>memoryLinkPair</code></td><td>adapters</td></tr><tr><td><code>ChildProcessLink</code>, <code>ChildProcessLinkOptions</code>, <code>IpcProcess</code></td><td>types for the server-side adapter</td></tr></tbody></table><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to “Interfaces”">​</a></h2><h3 id="childprocesslink" tabindex="-1">ChildProcessLink <a class="header-anchor" href="#childprocesslink" aria-label="Permalink to “ChildProcessLink”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/childProcessLink.ts#L29" target="_blank" rel="noreferrer">childProcessLink.ts:29</a></p><p>A <a href="#messagelink">MessageLink</a> over the IPC channel of the current process, with a <code>flush</code> for the shutdown path: Node discards IPC writes still queued when <code>process.exit</code> runs, so the server awaits <code>flush()</code> before exiting to get its last messages out.</p><h4 id="extends" tabindex="-1">Extends <a class="header-anchor" href="#extends" aria-label="Permalink to “Extends”">​</a></h4><ul><li><a href="#messagelink"><code>MessageLink</code></a>&lt;<code>In</code>, <code>Out</code>&gt;</li></ul><h4 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="in" tabindex="-1">In <a class="header-anchor" href="#in" aria-label="Permalink to “In”">​</a></h5><p><code>In</code></p><h5 id="out" tabindex="-1">Out <a class="header-anchor" href="#out" aria-label="Permalink to “Out”">​</a></h5><p><code>Out</code></p><h4 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h4><h5 id="close" tabindex="-1">close() <a class="header-anchor" href="#close" aria-label="Permalink to “close()”">​</a></h5><blockquote><p><strong>close</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/link.ts#L38" target="_blank" rel="noreferrer">link.ts:38</a></p><p>Closes the channel. Calling it more than once has no further effect.</p><h6 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h6><p><code>void</code></p><h6 id="inherited-from" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from" aria-label="Permalink to “Inherited from”">​</a></h6><p><a href="#messagelink"><code>MessageLink</code></a>.<a href="#close-1"><code>close</code></a></p><h5 id="flush" tabindex="-1">flush() <a class="header-anchor" href="#flush" aria-label="Permalink to “flush()”">​</a></h5><blockquote><p><strong>flush</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/childProcessLink.ts#L31" target="_blank" rel="noreferrer">childProcessLink.ts:31</a></p><p>Resolves once Node has written every message queued so far to the channel, or once the channel has closed.</p><h6 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h6><p><code>Promise</code>&lt;<code>void</code>&gt;</p><h5 id="onclose" tabindex="-1">onClose() <a class="header-anchor" href="#onclose" aria-label="Permalink to “onClose()”">​</a></h5><blockquote><p><strong>onClose</strong>(<code>listener</code>): () =&gt; <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/link.ts#L35" target="_blank" rel="noreferrer">link.ts:35</a></p><p>Registers a listener that runs once when the channel closes, whether this end called <a href="#close-1">close</a> or the other end went away. Listeners run in registration order.</p><h6 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="listener" tabindex="-1">listener <a class="header-anchor" href="#listener" aria-label="Permalink to “listener”">​</a></h6><p>() =&gt; <code>void</code></p><h6 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h6><p>A function that removes the listener.</p><p>() =&gt; <code>void</code></p><h6 id="inherited-from-1" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-1" aria-label="Permalink to “Inherited from”">​</a></h6><p><a href="#messagelink"><code>MessageLink</code></a>.<a href="#onclose-1"><code>onClose</code></a></p><h5 id="onmessage" tabindex="-1">onMessage() <a class="header-anchor" href="#onmessage" aria-label="Permalink to “onMessage()”">​</a></h5><blockquote><p><strong>onMessage</strong>(<code>listener</code>): () =&gt; <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/link.ts#L27" target="_blank" rel="noreferrer">link.ts:27</a></p><p>Registers a listener for incoming messages. Listeners run in registration order, one after another, for each message.</p><h6 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="listener-1" tabindex="-1">listener <a class="header-anchor" href="#listener-1" aria-label="Permalink to “listener”">​</a></h6><p>(<code>message</code>) =&gt; <code>void</code></p><h6 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h6><p>A function that removes the listener.</p><p>() =&gt; <code>void</code></p><h6 id="inherited-from-2" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-2" aria-label="Permalink to “Inherited from”">​</a></h6><p><a href="#messagelink"><code>MessageLink</code></a>.<a href="#onmessage-1"><code>onMessage</code></a></p><h5 id="send" tabindex="-1">send() <a class="header-anchor" href="#send" aria-label="Permalink to “send()”">​</a></h5><blockquote><p><strong>send</strong>(<code>message</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/link.ts#L19" target="_blank" rel="noreferrer">link.ts:19</a></p><p>Queues a message for the other end.</p><h6 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="message" tabindex="-1">message <a class="header-anchor" href="#message" aria-label="Permalink to “message”">​</a></h6><p><code>Out</code></p><h6 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h6><p><code>boolean</code></p><p><code>true</code> when the channel accepted the message. <code>false</code> means the channel asked for a pause, either because its unsent backlog passed the adapter&#39;s threshold or because it has closed. Nothing is dropped by the adapter on <code>false</code>; the sender may keep sending, but it should cap its own queue because every queued message stays in memory until the receiver reads it.</p><h6 id="inherited-from-3" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-3" aria-label="Permalink to “Inherited from”">​</a></h6><p><a href="#messagelink"><code>MessageLink</code></a>.<a href="#send-2"><code>send</code></a></p><hr><h3 id="childprocesslinkoptions" tabindex="-1">ChildProcessLinkOptions <a class="header-anchor" href="#childprocesslinkoptions" aria-label="Permalink to “ChildProcessLinkOptions”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/childProcessLink.ts#L19" target="_blank" rel="noreferrer">childProcessLink.ts:19</a></p><p>Options for <a href="#childprocesslink-1">childProcessLink</a>.</p><h4 id="extends-1" tabindex="-1">Extends <a class="header-anchor" href="#extends-1" aria-label="Permalink to “Extends”">​</a></h4><ul><li><a href="#linkoptions"><code>LinkOptions</code></a>&lt;<code>In</code>&gt;</li></ul><h4 id="type-parameters-1" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-1" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="in-1" tabindex="-1">In <a class="header-anchor" href="#in-1" aria-label="Permalink to “In”">​</a></h5><p><code>In</code></p><h4 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h4><h5 id="proc" tabindex="-1">proc? <a class="header-anchor" href="#proc" aria-label="Permalink to “proc?”">​</a></h5><blockquote><p><code>optional</code> <strong>proc?</strong>: <a href="#ipcprocess"><code>IpcProcess</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/childProcessLink.ts#L21" target="_blank" rel="noreferrer">childProcessLink.ts:21</a></p><p>The process whose IPC channel carries the messages. Defaults to the current <code>process</code>.</p><h5 id="validate" tabindex="-1">validate <a class="header-anchor" href="#validate" aria-label="Permalink to “validate”">​</a></h5><blockquote><p><strong>validate</strong>: (<code>value</code>) =&gt; <code>value is In</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/link.ts#L48" target="_blank" rel="noreferrer">link.ts:48</a></p><p>Type guard applied to every incoming message, typically <code>isServerMessage</code> or <code>isConsoleMessage</code>.</p><h6 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="value" tabindex="-1">value <a class="header-anchor" href="#value" aria-label="Permalink to “value”">​</a></h6><p><code>unknown</code></p><h6 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h6><p><code>value is In</code></p><h6 id="inherited-from-4" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-4" aria-label="Permalink to “Inherited from”">​</a></h6><p><a href="#linkoptions"><code>LinkOptions</code></a>.<a href="#validate-1"><code>validate</code></a></p><hr><h3 id="ipcprocess" tabindex="-1">IpcProcess <a class="header-anchor" href="#ipcprocess" aria-label="Permalink to “IpcProcess”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/childProcessLink.ts#L8" target="_blank" rel="noreferrer">childProcessLink.ts:8</a></p><p>The parts of <code>process</code> the server-side link uses. <code>process</code> satisfies it when Node started the process with an <code>&#39;ipc&#39;</code> stdio entry; tests can pass a double.</p><h4 id="properties-1" tabindex="-1">Properties <a class="header-anchor" href="#properties-1" aria-label="Permalink to “Properties”">​</a></h4><h5 id="connected" tabindex="-1">connected <a class="header-anchor" href="#connected" aria-label="Permalink to “connected”">​</a></h5><blockquote><p><strong>connected</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/childProcessLink.ts#L9" target="_blank" rel="noreferrer">childProcessLink.ts:9</a></p><h4 id="methods-1" tabindex="-1">Methods <a class="header-anchor" href="#methods-1" aria-label="Permalink to “Methods”">​</a></h4><h5 id="disconnect" tabindex="-1">disconnect()? <a class="header-anchor" href="#disconnect" aria-label="Permalink to “disconnect()?”">​</a></h5><blockquote><p><code>optional</code> <strong>disconnect</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/childProcessLink.ts#L11" target="_blank" rel="noreferrer">childProcessLink.ts:11</a></p><h6 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h6><p><code>void</code></p><h5 id="off" tabindex="-1">off() <a class="header-anchor" href="#off" aria-label="Permalink to “off()”">​</a></h5><h6 id="call-signature" tabindex="-1">Call Signature <a class="header-anchor" href="#call-signature" aria-label="Permalink to “Call Signature”">​</a></h6><blockquote><p><strong>off</strong>(<code>event</code>, <code>listener</code>): <code>unknown</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/childProcessLink.ts#L14" target="_blank" rel="noreferrer">childProcessLink.ts:14</a></p><h6 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="event" tabindex="-1">event <a class="header-anchor" href="#event" aria-label="Permalink to “event”">​</a></h6><p><code>&quot;message&quot;</code></p><h6 id="listener-2" tabindex="-1">listener <a class="header-anchor" href="#listener-2" aria-label="Permalink to “listener”">​</a></h6><p>(<code>message</code>) =&gt; <code>void</code></p><h6 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h6><p><code>unknown</code></p><h6 id="call-signature-1" tabindex="-1">Call Signature <a class="header-anchor" href="#call-signature-1" aria-label="Permalink to “Call Signature”">​</a></h6><blockquote><p><strong>off</strong>(<code>event</code>, <code>listener</code>): <code>unknown</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/childProcessLink.ts#L15" target="_blank" rel="noreferrer">childProcessLink.ts:15</a></p><h6 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="event-1" tabindex="-1">event <a class="header-anchor" href="#event-1" aria-label="Permalink to “event”">​</a></h6><p><code>&quot;disconnect&quot;</code></p><h6 id="listener-3" tabindex="-1">listener <a class="header-anchor" href="#listener-3" aria-label="Permalink to “listener”">​</a></h6><p>() =&gt; <code>void</code></p><h6 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h6><p><code>unknown</code></p><h5 id="on" tabindex="-1">on() <a class="header-anchor" href="#on" aria-label="Permalink to “on()”">​</a></h5><h6 id="call-signature-2" tabindex="-1">Call Signature <a class="header-anchor" href="#call-signature-2" aria-label="Permalink to “Call Signature”">​</a></h6><blockquote><p><strong>on</strong>(<code>event</code>, <code>listener</code>): <code>unknown</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/childProcessLink.ts#L12" target="_blank" rel="noreferrer">childProcessLink.ts:12</a></p><h6 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="event-2" tabindex="-1">event <a class="header-anchor" href="#event-2" aria-label="Permalink to “event”">​</a></h6><p><code>&quot;message&quot;</code></p><h6 id="listener-4" tabindex="-1">listener <a class="header-anchor" href="#listener-4" aria-label="Permalink to “listener”">​</a></h6><p>(<code>message</code>) =&gt; <code>void</code></p><h6 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h6><p><code>unknown</code></p><h6 id="call-signature-3" tabindex="-1">Call Signature <a class="header-anchor" href="#call-signature-3" aria-label="Permalink to “Call Signature”">​</a></h6><blockquote><p><strong>on</strong>(<code>event</code>, <code>listener</code>): <code>unknown</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/childProcessLink.ts#L13" target="_blank" rel="noreferrer">childProcessLink.ts:13</a></p><h6 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="event-3" tabindex="-1">event <a class="header-anchor" href="#event-3" aria-label="Permalink to “event”">​</a></h6><p><code>&quot;disconnect&quot;</code></p><h6 id="listener-5" tabindex="-1">listener <a class="header-anchor" href="#listener-5" aria-label="Permalink to “listener”">​</a></h6><p>() =&gt; <code>void</code></p><h6 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h6><p><code>unknown</code></p><h5 id="send-1" tabindex="-1">send()? <a class="header-anchor" href="#send-1" aria-label="Permalink to “send()?”">​</a></h5><blockquote><p><code>optional</code> <strong>send</strong>(<code>message</code>, <code>sendHandle?</code>, <code>options?</code>, <code>callback?</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/childProcessLink.ts#L10" target="_blank" rel="noreferrer">childProcessLink.ts:10</a></p><h6 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="message-1" tabindex="-1">message <a class="header-anchor" href="#message-1" aria-label="Permalink to “message”">​</a></h6><p><code>unknown</code></p><h6 id="sendhandle" tabindex="-1">sendHandle? <a class="header-anchor" href="#sendhandle" aria-label="Permalink to “sendHandle?”">​</a></h6><p><code>unknown</code></p><h6 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h6><p><code>unknown</code></p><h6 id="callback" tabindex="-1">callback? <a class="header-anchor" href="#callback" aria-label="Permalink to “callback?”">​</a></h6><p>(<code>error</code>) =&gt; <code>void</code></p><h6 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h6><p><code>boolean</code></p><hr><h3 id="linkoptions" tabindex="-1">LinkOptions <a class="header-anchor" href="#linkoptions" aria-label="Permalink to “LinkOptions”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/link.ts#L46" target="_blank" rel="noreferrer">link.ts:46</a></p><p>Options shared by the adapters that read from another process. Incoming data is JSON the other side wrote, so the adapter cannot know its type; <code>validate</code> decides, and anything it rejects is dropped without a throw.</p><h4 id="extended-by" tabindex="-1">Extended by <a class="header-anchor" href="#extended-by" aria-label="Permalink to “Extended by”">​</a></h4><ul><li><a href="#childprocesslinkoptions"><code>ChildProcessLinkOptions</code></a></li></ul><h4 id="type-parameters-2" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-2" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="in-2" tabindex="-1">In <a class="header-anchor" href="#in-2" aria-label="Permalink to “In”">​</a></h5><p><code>In</code></p><h4 id="properties-2" tabindex="-1">Properties <a class="header-anchor" href="#properties-2" aria-label="Permalink to “Properties”">​</a></h4><h5 id="validate-1" tabindex="-1">validate <a class="header-anchor" href="#validate-1" aria-label="Permalink to “validate”">​</a></h5><blockquote><p><strong>validate</strong>: (<code>value</code>) =&gt; <code>value is In</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/link.ts#L48" target="_blank" rel="noreferrer">link.ts:48</a></p><p>Type guard applied to every incoming message, typically <code>isServerMessage</code> or <code>isConsoleMessage</code>.</p><h6 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="value-1" tabindex="-1">value <a class="header-anchor" href="#value-1" aria-label="Permalink to “value”">​</a></h6><p><code>unknown</code></p><h6 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to “Returns”">​</a></h6><p><code>value is In</code></p><hr><h3 id="logentry" tabindex="-1">LogEntry <a class="header-anchor" href="#logentry" aria-label="Permalink to “LogEntry”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L25" target="_blank" rel="noreferrer">messages.ts:25</a></p><p>One log record as the server forwards it to the console.</p><p><code>seq</code> increases by one per record so the console can detect a gap even when a <code>log.dropped</code> message is itself lost. <code>at</code> is epoch milliseconds so the console formats the time for its own zone. <code>formatted</code> is the ANSI line the logger would have printed itself.</p><h4 id="properties-3" tabindex="-1">Properties <a class="header-anchor" href="#properties-3" aria-label="Permalink to “Properties”">​</a></h4><h5 id="at" tabindex="-1">at <a class="header-anchor" href="#at" aria-label="Permalink to “at”">​</a></h5><blockquote><p><strong>at</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L29" target="_blank" rel="noreferrer">messages.ts:29</a></p><h5 id="formatted" tabindex="-1">formatted <a class="header-anchor" href="#formatted" aria-label="Permalink to “formatted”">​</a></h5><blockquote><p><strong>formatted</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L31" target="_blank" rel="noreferrer">messages.ts:31</a></p><h5 id="level" tabindex="-1">level <a class="header-anchor" href="#level" aria-label="Permalink to “level”">​</a></h5><blockquote><p><strong>level</strong>: <code>&quot;error&quot;</code> | <code>&quot;warn&quot;</code> | <code>&quot;info&quot;</code> | <code>&quot;verbose&quot;</code> | <code>&quot;debug&quot;</code> | <code>&quot;silly&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L27" target="_blank" rel="noreferrer">messages.ts:27</a></p><h5 id="message-2" tabindex="-1">message <a class="header-anchor" href="#message-2" aria-label="Permalink to “message”">​</a></h5><blockquote><p><strong>message</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L30" target="_blank" rel="noreferrer">messages.ts:30</a></p><h5 id="namespace" tabindex="-1">namespace <a class="header-anchor" href="#namespace" aria-label="Permalink to “namespace”">​</a></h5><blockquote><p><strong>namespace</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L28" target="_blank" rel="noreferrer">messages.ts:28</a></p><h5 id="seq" tabindex="-1">seq <a class="header-anchor" href="#seq" aria-label="Permalink to “seq”">​</a></h5><blockquote><p><strong>seq</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L26" target="_blank" rel="noreferrer">messages.ts:26</a></p><hr><h3 id="messagelink" tabindex="-1">MessageLink <a class="header-anchor" href="#messagelink" aria-label="Permalink to “MessageLink”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/link.ts#L9" target="_blank" rel="noreferrer">link.ts:9</a></p><p>One end of a two-way message channel between the server and the console.</p><p><code>In</code> is what this end receives and <code>Out</code> what it sends, so the server holds a <code>MessageLink&lt;ConsoleMessage, ServerMessage&gt;</code> and the console the mirror image. Adapters carry the messages over an IPC channel or, in tests, over memory; callers see only this interface.</p><h4 id="extended-by-1" tabindex="-1">Extended by <a class="header-anchor" href="#extended-by-1" aria-label="Permalink to “Extended by”">​</a></h4><ul><li><a href="#childprocesslink"><code>ChildProcessLink</code></a></li></ul><h4 id="type-parameters-3" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-3" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="in-3" tabindex="-1">In <a class="header-anchor" href="#in-3" aria-label="Permalink to “In”">​</a></h5><p><code>In</code></p><h5 id="out-1" tabindex="-1">Out <a class="header-anchor" href="#out-1" aria-label="Permalink to “Out”">​</a></h5><p><code>Out</code></p><h4 id="methods-2" tabindex="-1">Methods <a class="header-anchor" href="#methods-2" aria-label="Permalink to “Methods”">​</a></h4><h5 id="close-1" tabindex="-1">close() <a class="header-anchor" href="#close-1" aria-label="Permalink to “close()”">​</a></h5><blockquote><p><strong>close</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/link.ts#L38" target="_blank" rel="noreferrer">link.ts:38</a></p><p>Closes the channel. Calling it more than once has no further effect.</p><h6 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to “Returns”">​</a></h6><p><code>void</code></p><h5 id="onclose-1" tabindex="-1">onClose() <a class="header-anchor" href="#onclose-1" aria-label="Permalink to “onClose()”">​</a></h5><blockquote><p><strong>onClose</strong>(<code>listener</code>): () =&gt; <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/link.ts#L35" target="_blank" rel="noreferrer">link.ts:35</a></p><p>Registers a listener that runs once when the channel closes, whether this end called <a href="#close-1">close</a> or the other end went away. Listeners run in registration order.</p><h6 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="listener-6" tabindex="-1">listener <a class="header-anchor" href="#listener-6" aria-label="Permalink to “listener”">​</a></h6><p>() =&gt; <code>void</code></p><h6 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to “Returns”">​</a></h6><p>A function that removes the listener.</p><p>() =&gt; <code>void</code></p><h5 id="onmessage-1" tabindex="-1">onMessage() <a class="header-anchor" href="#onmessage-1" aria-label="Permalink to “onMessage()”">​</a></h5><blockquote><p><strong>onMessage</strong>(<code>listener</code>): () =&gt; <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/link.ts#L27" target="_blank" rel="noreferrer">link.ts:27</a></p><p>Registers a listener for incoming messages. Listeners run in registration order, one after another, for each message.</p><h6 id="parameters-11" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-11" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="listener-7" tabindex="-1">listener <a class="header-anchor" href="#listener-7" aria-label="Permalink to “listener”">​</a></h6><p>(<code>message</code>) =&gt; <code>void</code></p><h6 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to “Returns”">​</a></h6><p>A function that removes the listener.</p><p>() =&gt; <code>void</code></p><h5 id="send-2" tabindex="-1">send() <a class="header-anchor" href="#send-2" aria-label="Permalink to “send()”">​</a></h5><blockquote><p><strong>send</strong>(<code>message</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/link.ts#L19" target="_blank" rel="noreferrer">link.ts:19</a></p><p>Queues a message for the other end.</p><h6 id="parameters-12" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-12" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="message-3" tabindex="-1">message <a class="header-anchor" href="#message-3" aria-label="Permalink to “message”">​</a></h6><p><code>Out</code></p><h6 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to “Returns”">​</a></h6><p><code>boolean</code></p><p><code>true</code> when the channel accepted the message. <code>false</code> means the channel asked for a pause, either because its unsent backlog passed the adapter&#39;s threshold or because it has closed. Nothing is dropped by the adapter on <code>false</code>; the sender may keep sending, but it should cap its own queue because every queued message stays in memory until the receiver reads it.</p><h2 id="type-aliases" tabindex="-1">Type Aliases <a class="header-anchor" href="#type-aliases" aria-label="Permalink to “Type Aliases”">​</a></h2><h3 id="consolemessage" tabindex="-1">ConsoleMessage <a class="header-anchor" href="#consolemessage" aria-label="Permalink to “ConsoleMessage”">​</a></h3><blockquote><p><strong>ConsoleMessage</strong> = <code>Envelope</code>&lt;<code>&quot;command&quot;</code>&gt; &amp; <code>object</code> | <code>Envelope</code>&lt;<code>&quot;complete&quot;</code>&gt; &amp; <code>object</code> | <code>Envelope</code>&lt;<code>&quot;shutdown&quot;</code>&gt; | <code>Envelope</code>&lt;<code>&quot;subscribe&quot;</code>&gt; &amp; <code>object</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L67" target="_blank" rel="noreferrer">messages.ts:67</a></p><p>Messages the console sends to the server.</p><hr><h3 id="consolemessagetype" tabindex="-1">ConsoleMessageType <a class="header-anchor" href="#consolemessagetype" aria-label="Permalink to “ConsoleMessageType”">​</a></h3><blockquote><p><strong>ConsoleMessageType</strong> = <a href="#consolemessage"><code>ConsoleMessage</code></a>[<code>&quot;type&quot;</code>]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L77" target="_blank" rel="noreferrer">messages.ts:77</a></p><p>The <code>type</code> of a <a href="#consolemessage">ConsoleMessage</a>.</p><hr><h3 id="ipcchild" tabindex="-1">IpcChild <a class="header-anchor" href="#ipcchild" aria-label="Permalink to “IpcChild”">​</a></h3><blockquote><p><strong>IpcChild</strong> = <code>Pick</code>&lt;<code>ChildProcess</code>, <code>&quot;connected&quot;</code> | <code>&quot;send&quot;</code> | <code>&quot;disconnect&quot;</code> | <code>&quot;on&quot;</code> | <code>&quot;off&quot;</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/subprocessLink.ts#L9" target="_blank" rel="noreferrer">subprocessLink.ts:9</a></p><p>The part of a <code>ChildProcess</code> the link reads: the IPC channel and its lifecycle events. A real child satisfies it; tests pass an emitter with the same members.</p><hr><h3 id="lifecyclestate" tabindex="-1">LifecycleState <a class="header-anchor" href="#lifecyclestate" aria-label="Permalink to “LifecycleState”">​</a></h3><blockquote><p><strong>LifecycleState</strong> = <em>typeof</em> <a href="#lifecycle-states"><code>LIFECYCLE_STATES</code></a>[<code>number</code>]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L38" target="_blank" rel="noreferrer">messages.ts:38</a></p><p>One of <a href="#lifecycle-states">LIFECYCLE_STATES</a>.</p><hr><h3 id="servermessage" tabindex="-1">ServerMessage <a class="header-anchor" href="#servermessage" aria-label="Permalink to “ServerMessage”">​</a></h3><blockquote><p><strong>ServerMessage</strong> = <code>Envelope</code>&lt;<code>&quot;hello&quot;</code>&gt; &amp; <code>object</code> | <code>Envelope</code>&lt;<code>&quot;log&quot;</code>&gt; &amp; <a href="#logentry"><code>LogEntry</code></a> | <code>Envelope</code>&lt;<code>&quot;log.dropped&quot;</code>&gt; &amp; <code>object</code> | <code>Envelope</code>&lt;<code>&quot;status&quot;</code>&gt; &amp; <code>object</code> | <code>Envelope</code>&lt;<code>&quot;lifecycle&quot;</code>&gt; &amp; <code>object</code> | <code>Envelope</code>&lt;<code>&quot;command.result&quot;</code>&gt; &amp; <code>object</code> | <code>Envelope</code>&lt;<code>&quot;complete.result&quot;</code>&gt; &amp; <code>object</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L46" target="_blank" rel="noreferrer">messages.ts:46</a></p><p>Messages the server sends to the console.</p><hr><h3 id="servermessagetype" tabindex="-1">ServerMessageType <a class="header-anchor" href="#servermessagetype" aria-label="Permalink to “ServerMessageType”">​</a></h3><blockquote><p><strong>ServerMessageType</strong> = <a href="#servermessage"><code>ServerMessage</code></a>[<code>&quot;type&quot;</code>]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L74" target="_blank" rel="noreferrer">messages.ts:74</a></p><p>The <code>type</code> of a <a href="#servermessage">ServerMessage</a>.</p><hr><h3 id="supervisorevent" tabindex="-1">SupervisorEvent <a class="header-anchor" href="#supervisorevent" aria-label="Permalink to “SupervisorEvent”">​</a></h3><blockquote><p><strong>SupervisorEvent</strong> = { <code>code?</code>: <code>number</code> | <code>null</code>; <code>generation</code>: <code>number</code>; <code>signal?</code>: <code>string</code> | <code>null</code>; <code>state</code>: <a href="#supervisorstate"><code>SupervisorState</code></a>; <code>type</code>: <code>&quot;supervisor.state&quot;</code>; } | { <code>canRestart?</code>: <code>boolean</code>; <code>root</code>: <code>string</code>; <code>type</code>: <code>&quot;supervisor.watching&quot;</code>; } | { <code>path</code>: <code>string</code>; <code>type</code>: <code>&quot;supervisor.changed&quot;</code>; } | { <code>ok?</code>: <code>boolean</code>; <code>type</code>: <code>&quot;supervisor.generating&quot;</code>; } | { <code>stream</code>: <code>&quot;stdout&quot;</code> | <code>&quot;stderr&quot;</code>; <code>text</code>: <code>string</code>; <code>type</code>: <code>&quot;supervisor.output&quot;</code>; }</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L87" target="_blank" rel="noreferrer">messages.ts:87</a></p><p>Events the host raises about the server child. They never cross the IPC channel; the host produces them from the child&#39;s exit status, the file watcher, and the child&#39;s stdio pipes, and the console renders them as status and toasts rather than log lines.</p><h4 id="union-members" tabindex="-1">Union Members <a class="header-anchor" href="#union-members" aria-label="Permalink to “Union Members”">​</a></h4><h5 id="type-literal" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal" aria-label="Permalink to “Type Literal”">​</a></h5><p>{ <code>code?</code>: <code>number</code> | <code>null</code>; <code>generation</code>: <code>number</code>; <code>signal?</code>: <code>string</code> | <code>null</code>; <code>state</code>: <a href="#supervisorstate"><code>SupervisorState</code></a>; <code>type</code>: <code>&quot;supervisor.state&quot;</code>; }</p><hr><h5 id="type-literal-1" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal-1" aria-label="Permalink to “Type Literal”">​</a></h5><p>{ <code>canRestart?</code>: <code>boolean</code>; <code>root</code>: <code>string</code>; <code>type</code>: <code>&quot;supervisor.watching&quot;</code>; }</p><h6 id="canrestart" tabindex="-1">canRestart? <a class="header-anchor" href="#canrestart" aria-label="Permalink to “canRestart?”">​</a></h6><blockquote><p><code>optional</code> <strong>canRestart?</strong>: <code>boolean</code></p></blockquote><p>Whether the host will act on a restart request. Set by the supervisor on the way out; a frontend treats a missing value as false.</p><h6 id="root" tabindex="-1">root <a class="header-anchor" href="#root" aria-label="Permalink to “root”">​</a></h6><blockquote><p><strong>root</strong>: <code>string</code></p></blockquote><h6 id="type" tabindex="-1">type <a class="header-anchor" href="#type" aria-label="Permalink to “type”">​</a></h6><blockquote><p><strong>type</strong>: <code>&quot;supervisor.watching&quot;</code></p></blockquote><hr><h5 id="type-literal-2" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal-2" aria-label="Permalink to “Type Literal”">​</a></h5><p>{ <code>path</code>: <code>string</code>; <code>type</code>: <code>&quot;supervisor.changed&quot;</code>; }</p><hr><h5 id="type-literal-3" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal-3" aria-label="Permalink to “Type Literal”">​</a></h5><p>{ <code>ok?</code>: <code>boolean</code>; <code>type</code>: <code>&quot;supervisor.generating&quot;</code>; }</p><hr><h5 id="type-literal-4" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal-4" aria-label="Permalink to “Type Literal”">​</a></h5><p>{ <code>stream</code>: <code>&quot;stdout&quot;</code> | <code>&quot;stderr&quot;</code>; <code>text</code>: <code>string</code>; <code>type</code>: <code>&quot;supervisor.output&quot;</code>; }</p><hr><h3 id="supervisorstate" tabindex="-1">SupervisorState <a class="header-anchor" href="#supervisorstate" aria-label="Permalink to “SupervisorState”">​</a></h3><blockquote><p><strong>SupervisorState</strong> = <code>&quot;starting&quot;</code> | <code>&quot;running&quot;</code> | <code>&quot;stopping&quot;</code> | <code>&quot;stopped&quot;</code> | <code>&quot;crashed&quot;</code> | <code>&quot;restarting&quot;</code> | <code>&quot;waiting&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L80" target="_blank" rel="noreferrer">messages.ts:80</a></p><p>States of the host&#39;s supervisor, which owns the server child process.</p><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to “Variables”">​</a></h2><h3 id="lifecycle-states" tabindex="-1">LIFECYCLE_STATES <a class="header-anchor" href="#lifecycle-states" aria-label="Permalink to “LIFECYCLE_STATES”">​</a></h3><blockquote><p><code>const</code> <strong>LIFECYCLE_STATES</strong>: readonly [<code>&quot;starting&quot;</code>, <code>&quot;running&quot;</code>, <code>&quot;stopping&quot;</code>]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L35" target="_blank" rel="noreferrer">messages.ts:35</a></p><p>Server lifecycle states reported over the link. <code>stopped</code> and <code>crashed</code> come from the child&#39;s exit, not a message.</p><hr><h3 id="protocol-version" tabindex="-1">PROTOCOL_VERSION <a class="header-anchor" href="#protocol-version" aria-label="Permalink to “PROTOCOL_VERSION”">​</a></h3><blockquote><p><code>const</code> <strong>PROTOCOL_VERSION</strong>: <code>1</code> = <code>1</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L11" target="_blank" rel="noreferrer">messages.ts:11</a></p><p>Version of the message schema. Both sides stamp it on every message as <code>v</code>, and the type guards reject messages from another version so a mismatched host and server fail loudly instead of misreading each other.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h2><h3 id="childprocesslink-1" tabindex="-1">childProcessLink() <a class="header-anchor" href="#childprocesslink-1" aria-label="Permalink to “childProcessLink()”">​</a></h3><blockquote><p><strong>childProcessLink</strong>&lt;<code>In</code>, <code>Out</code>&gt;(<code>options</code>): <a href="#childprocesslink"><code>ChildProcessLink</code></a>&lt;<code>In</code>, <code>Out</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/childProcessLink.ts#L50" target="_blank" rel="noreferrer">childProcessLink.ts:50</a></p><p>Builds the server-side link over the IPC channel Node opens when the host forks the server with an <code>&#39;ipc&#39;</code> stdio entry. Messages travel through <code>process.send</code> in Node&#39;s JSON mode, so they must be plain JSON values. Registering a message listener makes the channel keep the process alive until it disconnects.</p><p><code>send</code> returns what <code>process.send</code> returns: <code>false</code> once the unsent backlog passes Node&#39;s threshold or after the channel closed. The close listeners run when the channel disconnects, whether through <a href="#close-1">MessageLink.close</a> or because the host went away. A channel that is already disconnected when the link is built, because the host went away during startup, is reported the same way: the close listeners run on the next microtask, which leaves the caller its synchronous turn to register them, so the server still learns to shut down.</p><h4 id="type-parameters-4" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-4" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="in-4" tabindex="-1">In <a class="header-anchor" href="#in-4" aria-label="Permalink to “In”">​</a></h5><p><code>In</code></p><h5 id="out-2" tabindex="-1">Out <a class="header-anchor" href="#out-2" aria-label="Permalink to “Out”">​</a></h5><p><code>Out</code></p><h4 id="parameters-13" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-13" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options-1" tabindex="-1">options <a class="header-anchor" href="#options-1" aria-label="Permalink to “options”">​</a></h5><p><a href="#childprocesslinkoptions"><code>ChildProcessLinkOptions</code></a>&lt;<code>In</code>&gt;</p><h4 id="returns-17" tabindex="-1">Returns <a class="header-anchor" href="#returns-17" aria-label="Permalink to “Returns”">​</a></h4><p><a href="#childprocesslink"><code>ChildProcessLink</code></a>&lt;<code>In</code>, <code>Out</code>&gt;</p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>When the process has no IPC channel, which means it was not started by <code>child_process.fork</code> or with an <code>&#39;ipc&#39;</code> stdio entry.</p><hr><h3 id="isconsolemessage" tabindex="-1">isConsoleMessage() <a class="header-anchor" href="#isconsolemessage" aria-label="Permalink to “isConsoleMessage()”">​</a></h3><blockquote><p><strong>isConsoleMessage</strong>(<code>value</code>): <code>value is ConsoleMessage</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L210" target="_blank" rel="noreferrer">messages.ts:210</a></p><p>Whether a decoded JSON value is a <a href="#consolemessage">ConsoleMessage</a> of this protocol version with its required fields present and of the right kind. The <code>subscribe</code> level must be a log level.</p><h4 id="parameters-14" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-14" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="value-2" tabindex="-1">value <a class="header-anchor" href="#value-2" aria-label="Permalink to “value”">​</a></h5><p><code>unknown</code></p><h4 id="returns-18" tabindex="-1">Returns <a class="header-anchor" href="#returns-18" aria-label="Permalink to “Returns”">​</a></h4><p><code>value is ConsoleMessage</code></p><hr><h3 id="islifecyclestate" tabindex="-1">isLifecycleState() <a class="header-anchor" href="#islifecyclestate" aria-label="Permalink to “isLifecycleState()”">​</a></h3><blockquote><p><strong>isLifecycleState</strong>(<code>value</code>): value is &quot;starting&quot; | &quot;running&quot; | &quot;stopping&quot;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L41" target="_blank" rel="noreferrer">messages.ts:41</a></p><p>Whether a decoded value names one of <a href="#lifecycle-states">LIFECYCLE_STATES</a>.</p><h4 id="parameters-15" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-15" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="value-3" tabindex="-1">value <a class="header-anchor" href="#value-3" aria-label="Permalink to “value”">​</a></h5><p><code>unknown</code></p><h4 id="returns-19" tabindex="-1">Returns <a class="header-anchor" href="#returns-19" aria-label="Permalink to “Returns”">​</a></h4><p>value is &quot;starting&quot; | &quot;running&quot; | &quot;stopping&quot;</p><hr><h3 id="isservermessage" tabindex="-1">isServerMessage() <a class="header-anchor" href="#isservermessage" aria-label="Permalink to “isServerMessage()”">​</a></h3><blockquote><p><strong>isServerMessage</strong>(<code>value</code>): <code>value is ServerMessage</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/messages.ts#L199" target="_blank" rel="noreferrer">messages.ts:199</a></p><p>Whether a decoded JSON value is a <a href="#servermessage">ServerMessage</a> of this protocol version with its required fields present and of the right kind. Literal fields such as <code>level</code> and <code>state</code> must hold one of their declared values.</p><h4 id="parameters-16" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-16" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="value-4" tabindex="-1">value <a class="header-anchor" href="#value-4" aria-label="Permalink to “value”">​</a></h5><p><code>unknown</code></p><h4 id="returns-20" tabindex="-1">Returns <a class="header-anchor" href="#returns-20" aria-label="Permalink to “Returns”">​</a></h4><p><code>value is ServerMessage</code></p><hr><h3 id="memorylinkpair" tabindex="-1">memoryLinkPair() <a class="header-anchor" href="#memorylinkpair" aria-label="Permalink to “memoryLinkPair()”">​</a></h3><blockquote><p><strong>memoryLinkPair</strong>&lt;<code>A</code>, <code>B</code>&gt;(): [<a href="#messagelink"><code>MessageLink</code></a>&lt;<code>A</code>, <code>B</code>&gt;, <a href="#messagelink"><code>MessageLink</code></a>&lt;<code>B</code>, <code>A</code>&gt;]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/memoryLink.ts#L15" target="_blank" rel="noreferrer">memoryLink.ts:15</a></p><p>Two in-memory <a href="#messagelink">MessageLink</a>s wired to each other, for tests that need a server and a console in one process. Messages are delivered on a microtask, so <code>send</code> returns before any listener runs, as with a real channel. <code>close()</code> on either end runs the close listeners of both ends synchronously; messages still queued at that moment are dropped.</p><h4 id="type-parameters-5" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-5" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to “A”">​</a></h5><p><code>A</code></p><h5 id="b" tabindex="-1">B <a class="header-anchor" href="#b" aria-label="Permalink to “B”">​</a></h5><p><code>B</code></p><h4 id="returns-21" tabindex="-1">Returns <a class="header-anchor" href="#returns-21" aria-label="Permalink to “Returns”">​</a></h4><p>[<a href="#messagelink"><code>MessageLink</code></a>&lt;<code>A</code>, <code>B</code>&gt;, <a href="#messagelink"><code>MessageLink</code></a>&lt;<code>B</code>, <code>A</code>&gt;]</p><p>A tuple of the end that receives <code>A</code> and sends <code>B</code>, and the end that receives <code>B</code> and sends <code>A</code>.</p><hr><h3 id="subprocesslink" tabindex="-1">subprocessLink() <a class="header-anchor" href="#subprocesslink" aria-label="Permalink to “subprocessLink()”">​</a></h3><blockquote><p><strong>subprocessLink</strong>&lt;<code>In</code>, <code>Out</code>&gt;(<code>child</code>, <code>options</code>): <a href="#messagelink"><code>MessageLink</code></a>&lt;<code>In</code>, <code>Out</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/6d15958715f813affcd7add7dc44b431fe55d2b7/packages/console-protocol/src/subprocessLink.ts#L22" target="_blank" rel="noreferrer">subprocessLink.ts:22</a></p><p>Builds the host-side link to a server child spawned with an <code>&#39;ipc&#39;</code> stdio entry. Messages travel through <code>child.send</code>, and incoming ones pass <code>options.validate</code> before any listener sees them, so a stray JSON value from the child is dropped rather than thrown.</p><p>The link closes when the child&#39;s <code>&#39;close&#39;</code> or <code>&#39;exit&#39;</code> event fires or its channel disconnects. <code>&#39;close&#39;</code> is needed on its own: a spawn that fails (ENOENT, EAGAIN, EMFILE) emits <code>&#39;error&#39;</code> and <code>&#39;close&#39;</code> but never <code>&#39;exit&#39;</code>. <code>stopped</code> versus <code>crashed</code> is for the caller to derive from the child&#39;s exit code. <a href="#close-1">MessageLink.close</a> disconnects the channel but leaves the child running; stopping it is the supervisor&#39;s job.</p><h4 id="type-parameters-6" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-6" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="in-5" tabindex="-1">In <a class="header-anchor" href="#in-5" aria-label="Permalink to “In”">​</a></h5><p><code>In</code></p><h5 id="out-3" tabindex="-1">Out <a class="header-anchor" href="#out-3" aria-label="Permalink to “Out”">​</a></h5><p><code>Out</code> <em>extends</em> <code>Serializable</code></p><h4 id="parameters-17" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-17" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="child" tabindex="-1">child <a class="header-anchor" href="#child" aria-label="Permalink to “child”">​</a></h5><p><a href="#ipcchild"><code>IpcChild</code></a></p><h5 id="options-2" tabindex="-1">options <a class="header-anchor" href="#options-2" aria-label="Permalink to “options”">​</a></h5><p><a href="#linkoptions"><code>LinkOptions</code></a>&lt;<code>In</code>&gt;</p><h4 id="returns-22" tabindex="-1">Returns <a class="header-anchor" href="#returns-22" aria-label="Permalink to “Returns”">​</a></h4><p><a href="#messagelink"><code>MessageLink</code></a>&lt;<code>In</code>, <code>Out</code>&gt;</p>`,409)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};